export function takeWhile<T, U extends T>(array: readonly T[] | undefined, predicate: (element: T) => element is U): U[] | undefined;
export function takeWhile<T, U extends T>(array: readonly T[] | undefined, predicate: (element: T) => element is U): U[] | undefined {
    if (array !== undefined) {
        const result: U[] = [];
        const len = array.length;
        let index = 0;
        while (index < len) {
            const element = array[index]!;
            if (!predicate(element)) break;
            result.push(element);
            index++;
        }
        return result;
    }
}
